SELECT apply_date FROM ( SELECT DATE_FORMAT(apply_date, '%Y-%m-%d 00:00:00') AS apply_date FROM camp_leader WHERE campaign_id = #{campaignId} AND is_deleted = 'N' AND apply_date IS NOT NULL -- 👈 NULL인 날짜 제외
UNION
SELECT DATE_FORMAT(apply_date, '%Y-%m-%d 00:00:00') AS apply_date FROM user_campaign WHERE campaign_id = #{campaignId} AND is_deleted = 'N' AND apply_date IS NOT NULL -- 👈 NULL인 날짜 제외 ) combined_dates ORDER BY apply_date ASC;

