SELECT
    reason_info,
    amount
FROM point_history ph
WHERE ph.campaign_id = #{campaignId}
AND ph.mission_date = #{missionDate}
AND user_no = #{userNo}
and category = 'OVERPAY'


SELECT
    c.campaign_title,
    u.user_nm
FROM user_campaign uc
LEFT OUTER JOIN campaign c ON uc.campaign_id = c.campaign_id
LEFT OUTER JOIN user u ON uc.user_id = u.user_id
WHERE uc.user_no = #{userNo}
AND uc.is_leader = 'N'
AND uc.is_deleted = 'N'
AND (
    uc.event_str_date <= #{dto.eventPeriodEnd}
    AND uc.event_end_date >= #{dto.eventPeriodStr}
)
AND c.time_segment = #{dto.timeSegment}
LIMIT 1

